We're mid-upgrade from Umbraco 13 to 17. Everything compiles, but there are CS0618 warnings on RedirectCacheComponent, and the site now fails on startup with System.InvalidOperationException: 'Operation is not valid due to the current state of the object.', thrown at startup from the CreateUmbracoBuilder() chain in Program.cs. Separately, some of our deployments switch off the analytics feature with [assembly: DisableComposer(typeof(AnalyticsComposer))], and CampaignComposer needs to run after AnalyticsComposer when it's enabled, but the site must still boot when it's disabled. Here's the code (namespace Acme.Site.Infrastructure):

```csharp
public class RedirectCacheComposer : ComponentComposer<RedirectCacheComponent> { }

public class RedirectCacheComponent : IComponent
{
    private readonly IRedirectCache _cache;
    private readonly IRuntimeState _runtimeState;

    public RedirectCacheComponent(IRedirectCache cache, IRuntimeState runtimeState)
    {
        _cache = cache;
        _runtimeState = runtimeState;
    }

    public void Initialize()
    {
        if (_runtimeState.Level != RuntimeLevel.Run) return;
        _cache.LoadAllAsync().GetAwaiter().GetResult();
    }

    public void Terminate() => _cache.Flush();
}

public class CampaignComposer : IComposer
{
    public void Compose(IUmbracoBuilder builder)
    {
        builder.Services.AddSingleton<IRedirectCache, RedirectCache>();
        builder.ContentFinders().InsertBefore<ContentFinderByUrl, CampaignContentFinder>();
    }
}
```

Fix it for 17 and explain what was actually causing the startup crash.
